learningsession.calculateProbability:
               // Base5s/Base5f params: c(0.399536622972343, 0.0016614376588934, 0.336563528163593, 0.0178525018949322, 0.149628370083175, 0.119826991829039, 0.0372256128378958, 1e-04, 0.113386166480882, 0.681361486952463)
                // A demonstration of a variable that will be shown in the console
                p.CUSTOM_MSG = "In our custom function";

                //Base5suc (d is positive here because it is denominator
                p.baseLevelS = 1 / Math.pow(1 + p.questionSecsPracticingOthers + ((p.questionSecsSinceFirstShown - p.questionSecsPracticingOthers) * 0.00166),  0.3995);//par1 and par2
                p.meanSpacingS = 0;
                if (p.questionStudyTrialCount + p.questionTotalTests == 1) {
                    p.meanSpacingS = .01785*10; //Use par4 in here?
                } else {
                    if (p.questionStudyTrialCount + p.questionTotalTests > 1) {
                        p.meanSpacingS = Math.max(
                                1, Math.pow((p.questionSecsSinceFirstShown - p.questionSecsSinceLastShown) / (p.questionStudyTrialCount + p.questionTotalTests - 1), 0.336)//par3
                                );
                    }}
                p.intbsS = p.meanSpacingS * p.baseLevelS;

               // Base5fail (d is positive here because it is denominator
                p.baseLevelF = 1 / Math.pow(1 + p.questionSecsPracticingOthers + ((p.questionSecsSinceFirstShown - p.questionSecsPracticingOthers) * 0.0372),  0.1198);
                p.meanSpacingF = 0;
                if (p.questionStudyTrialCount + p.questionTotalTests == 1) {
                    p.meanSpacingF = .1133*10; //Use par4 in here?
                } else {
                    if (p.questionStudyTrialCount + p.questionTotalTests > 1) {
                        p.meanSpacingF = Math.max(
                                1, Math.pow((p.questionSecsSinceFirstShown - p.questionSecsSinceLastShown) / (p.questionStudyTrialCount + p.questionTotalTests - 1), 0.0001)
                                );
                    }}
                p.intbsF = p.meanSpacingF * p.baseLevelF;

                // Helpful to be able to see our y parameter for debugging
                
                //logit
                //p.logit = Math.log(1+p.questionSuccessCount)/Math.log(1+p.questionFailureCount)
                
//console.log("success counts")
//console.log(p.questionSuccessCount)
//console.log("failure counts")
//console.log(p.questionFailureCount)
                p.y = p.stimParameters[0] + 6.62 * p.intbsS * Math.log((0.149*10)+p.questionSuccessCount) + 4.07 * p.intbsF*Math.log((0.681*10)+p.questionFailureCount+p.questionStudyTrialCount); //avg subj int //+ .908*p.logit
       
//console.log("p.y without parseFloat")
 
// At a minimum we need to set p.probability and return p
                
                p.probability = 1.0 / (1.0 + Math.exp(-p.y));  // Actual probability
     
                return p;
